#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long y;
    long long a;
    int idx;
} Item;

int cmp1(const void *p, const void *q) {
    const Item *x = (const Item *)p;
    const Item *y = (const Item *)q;

    if (x->y < y->y) return -1;
    if (x->y > y->y) return 1;

    // At X1, tie by slope descending
    if (x->a > y->a) return -1;
    if (x->a < y->a) return 1;

    return (x->idx > y->idx) - (x->idx < y->idx);
}

int cmp2(const void *p, const void *q) {
    const Item *x = (const Item *)p;
    const Item *y = (const Item *)q;

    if (x->y < y->y) return -1;
    if (x->y > y->y) return 1;

    // At X2, tie by slope ascending
    if (x->a < y->a) return -1;
    if (x->a > y->a) return 1;

    return (x->idx > y->idx) - (x->idx < y->idx);
}

void bit_add(int *bit, int n, int idx, int val) {
    for (idx++; idx <= n; idx += idx & -idx) {
        bit[idx] += val;
    }
}

